import {CHOICES,SCENES,SOURCES,ARTIFACTS,createSession,setAnswer,setNote,calculateMetrics,buildRecord} from './model.mjs';
const $=id=>document.getElementById(id);
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session=createSession(),currentScene=0,currentArtifact='boxes',editing=false;
const radios=[...document.querySelectorAll('input[name=answer]')];
function announce(message){$('announcement').textContent=message;}
function header(){const m=calculateMetrics(session);$('record-count').textContent=`${m.answered}/6`;$('record-nav').disabled=!m.complete;$('restart-button').disabled=!m.answered&&!Object.values(session.notes).some(Boolean);}
function imageState(img,loading,error=false){const button=img.parentElement,status=button.querySelector('.image-status');button.setAttribute('aria-busy',String(loading));button.dataset.error=String(error);if(status){status.hidden=!loading&&!error;status.classList.toggle('error',error);status.textContent=error?'Photograph could not load. Select to retry.':'Loading photograph…';}}
for(const id of ['scene-image','artifact-image']){const img=$(id);img.addEventListener('load',()=>imageState(img,false));img.addEventListener('error',()=>imageState(img,false,true));}
function setImage(img,file,alt){img.alt=alt;imageState(img,true);img.src=`assets/${file}`;if(img.complete&&img.naturalWidth)imageState(img,false);}
function renderAnswer(){const scene=SCENES[currentScene],answer=session.answers[scene.id];radios.forEach(input=>input.checked=input.value===answer);$('next-button').disabled=!answer;$('reflection').hidden=!answer;if(answer){$('response-title').textContent=CHOICES.find(c=>c.id===answer).label;$('reflection-question').textContent=scene.question;$('context-button').hidden=!scene.research;}header();}
function renderScene(index,focus=false){currentScene=index;const scene=SCENES[index];$('simulation').hidden=false;$('results').hidden=true;$('stage-label').textContent=scene.short;$('step-description').textContent=`Decision ${index+1} of 6`;$('scene-title').textContent=scene.title;$('scene-story').textContent=scene.story;$('condition-label').textContent=scene.change;$('scene-condition').textContent=scene.condition;$('independence-note').hidden=index===0;setImage($('scene-image'),scene.image,scene.alt);$('scene-enlarge').setAttribute('aria-label',`Enlarge photograph: ${scene.alt}`);$('back-button').disabled=index===0;$('next-button').textContent=editing?'Update my record':index===0?'Explore the conditions →':index===5?'View my record →':'Next situation →';$('private-note').value=session.notes[scene.id];$('note-details').open=Boolean(session.notes[scene.id]);updateNoteMeta();renderAnswer();if(focus){$('scene-title').focus({preventScroll:true});window.scrollTo(0,0);}}
function updateNoteMeta(){const note=session.notes[SCENES[currentScene].id];$('note-count').textContent=`${note.length}/500`;$('note-indicator').textContent=note?'Saved for this visit':'Optional';header();}
function choose(choice){const scene=SCENES[currentScene];setAnswer(session,scene.id,choice);renderAnswer();announce(`${CHOICES.find(c=>c.id===choice).label}. ${scene.question}`);return {scene:scene.id,choice,question:scene.question};}
function route(focus=true){const hash=location.hash.slice(1);if(hash==='main-content')return;let target=hash==='record'?'record':SCENES.find(s=>s.id===hash)?.id||'offer';const m=calculateMetrics(session);if(target==='record'&&!m.complete)target=SCENES.find(s=>!session.answers[s.id]).id;let index=SCENES.findIndex(s=>s.id===target);if(index>=0){const missing=SCENES.findIndex((s,i)=>i<index&&!session.answers[s.id]);if(missing>=0){index=missing;target=SCENES[index].id;}}if(hash!==target)history.replaceState(null,'',`#${target}`);if(target==='record'){editing=false;renderResults(focus);}else renderScene(index,focus);if(hash==='artifacts')openDialog('artifact-dialog');if(hash==='about')openDialog('about-dialog');}
function go(target){if(location.hash===`#${target}`)route();else location.hash=target;}
window.addEventListener('hashchange',()=>route());
radios.forEach(input=>input.addEventListener('change',()=>choose(input.value)));
$('decision-form').addEventListener('submit',event=>{event.preventDefault();if(!session.answers[SCENES[currentScene].id])return;go(editing||currentScene===5?'record':SCENES[currentScene+1].id);});
$('back-button').addEventListener('click',()=>{editing=false;if(currentScene)go(SCENES[currentScene-1].id);});
$('private-note').addEventListener('input',()=>{setNote(session,SCENES[currentScene].id,$('private-note').value);updateNoteMeta();});
$('record-nav').addEventListener('click',()=>go('record'));
const compared=(scene,m)=>scene.id==='offer'?'Initial':session.answers[scene.id]===m.baseline?'Same':'Different';
function noteMarkup(scene){return session.notes[scene.id]?`<span class="row-note">${escapeHTML(session.notes[scene.id])}</span>`:'';}
function renderResults(focus=false){const m=calculateMetrics(session);$('simulation').hidden=true;$('results').hidden=false;$('stage-label').textContent='Your personal record';$('step-description').textContent='6 decisions complete';let observation;if(m.undecided===6)observation='You left all six decisions open. Revisit any situation, or keep the questions with you.';else if(m.differences===0)observation='Your answer stayed the same across all five situations. Which condition came closest to changing it?';else{const names=m.changed.map(id=>SCENES.find(s=>s.id===id).short.toLowerCase());observation=`Your answer differed from the original offer in ${m.differences===1?'one situation':`${m.differences} situations`}: ${names.join(', ')}. What mattered in those moments?`;}$('result-observation').textContent=observation;
$('metrics').innerHTML=`<div><dt>Differences from your initial answer</dt><dd>${m.differences}<span>of 5 situations</span></dd></div><div><dt>Undecided answers</dt><dd>${m.undecided}<span>of 6 decisions</span></dd></div><div><dt>Your choice counts</dt><dd class="distribution">${CHOICES.map(c=>`<div>${m.counts[c.id]}<span>${c.short}</span></div>`).join('')}</dd></div>`;
$('matrix-body').innerHTML=SCENES.map((s,i)=>`<tr><td><button class="revisit" data-revisit="${s.id}"><span class="row-number">${String(i+1).padStart(2,'0')}</span>${s.short}<span class="sr-only">, revise answer</span></button>${noteMarkup(s)}</td>${CHOICES.map(c=>`<td>${session.answers[s.id]===c.id?`<span class="matrix-dot" role="img" aria-label="${c.short} selected">●</span>`:'<span class="matrix-empty" aria-label="Not selected">·</span>'}</td>`).join('')}<td><span class="comparison ${compared(s,m)==='Different'?'different':''}">${compared(s,m)}</span></td></tr>`).join('');
$('mobile-matrix').innerHTML=SCENES.map((s,i)=>`<div class="mobile-row"><div><button class="revisit" data-revisit="${s.id}"><span class="row-number">${String(i+1).padStart(2,'0')}</span>${s.short}<span class="sr-only">, revise answer</span></button><span class="comparison ${compared(s,m)==='Different'?'different':''}">${compared(s,m)}</span></div><p class="mobile-answer">${CHOICES.find(c=>c.id===session.answers[s.id]).label}</p>${noteMarkup(s)}</div>`).join('');header();renderPrint();if(focus){$('result-title').focus({preventScroll:true});window.scrollTo(0,0);}}
$('results').addEventListener('click',event=>{const button=event.target.closest('[data-revisit]');if(button){editing=true;go(button.dataset.revisit);}});
function renderPrint(){if(!calculateMetrics(session).complete){$('printable-record').replaceChildren();return;}const record=buildRecord(session),lines=record.split('\n');$('printable-record').innerHTML=`<h1>DNA / The Choice</h1><p>${escapeHTML(lines.slice(1,8).join('\n'))}</p>${SCENES.map((s,i)=>`<div class="print-scene"><h3>${i+1}. ${s.short}</h3><p>${escapeHTML(s.story)}</p><p>Assumption: ${escapeHTML(s.condition)}</p><p>Answer: ${CHOICES.find(c=>c.id===session.answers[s.id]).label}<br>Compared: ${compared(s,calculateMetrics(session))}</p><p>Reflection: ${escapeHTML(s.question)}</p><p>Private note: ${escapeHTML(session.notes[s.id]||'(none)')}</p></div>`).join('')}<div class="print-sources"><h2>Sources and original project</h2>${SOURCES.map(s=>`<p>${s.title}<br>${escapeHTML(s.text)}<br><a href="${s.url}">${s.url}</a></p>`).join('')}<p>Original DNA project: Parth Pawar, NYU ITP, 2024.<br>https://designwhich.works/dna-speculative/</p><p>Responses stay in memory only. This printout includes your private notes.</p></div>`;}
$('download-record').addEventListener('click',()=>{const blob=new Blob([buildRecord(session)],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='dna-decision-record.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Your text record includes all six decisions and your notes.');});
$('print-record').addEventListener('click',()=>{renderPrint();window.print();});window.addEventListener('beforeprint',renderPrint);
function openDialog(id){const dialog=$(id);if(id==='artifact-dialog')selectArtifact(currentArtifact);if(id==='research-dialog')renderResearch(null);if(!dialog.open)dialog.showModal();}
document.querySelectorAll('[data-dialog]').forEach(button=>button.addEventListener('click',()=>openDialog(button.dataset.dialog)));
document.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();});
function renderResearch(highlight){$('research-content').innerHTML=SOURCES.map(s=>`<section class="source" data-highlight="${highlight===s.id}"><h3>${s.title}</h3><p>${s.text}</p><a href="${s.url}" target="_blank" rel="noopener">${s.label} ↗</a></section>`).join('');}
$('context-button').addEventListener('click',()=>{renderResearch(SCENES[currentScene].research);$('research-dialog').showModal();});
const tabs=[...document.querySelectorAll('[data-artifact]')];
function selectArtifact(id){const item=ARTIFACTS.find(a=>a.id===id);if(!item)throw new Error('Unknown artifact');currentArtifact=id;for(const tab of tabs){const active=tab.dataset.artifact===id;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;}$('artifact-panel').setAttribute('aria-labelledby',`artifact-tab-${id}`);$('artifact-title').textContent=item.title;$('artifact-description').textContent=item.text;setImage($('artifact-image'),item.file,item.alt);return {artifact:id,title:item.title};}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectArtifact(tab.dataset.artifact));tab.addEventListener('keydown',event=>{let next;if(['ArrowRight','ArrowDown'].includes(event.key))next=(i+1)%tabs.length;else if(['ArrowLeft','ArrowUp'].includes(event.key))next=(i+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();selectArtifact(tabs[next].dataset.artifact);tabs[next].focus();});});
function enlarge(img){if(img.parentElement.dataset.error==='true'){setImage(img,img.src.split('/').pop(),img.alt);return;}if(!img.complete||!img.naturalWidth)return;$('full-image').src=img.src;$('full-image').alt=img.alt;$('image-caption').textContent=img.alt;$('image-dialog').showModal();}
$('scene-enlarge').addEventListener('click',()=>enlarge($('scene-image')));$('artifact-enlarge').addEventListener('click',()=>enlarge($('artifact-image')));$('artifact-full-size').addEventListener('click',()=>enlarge($('artifact-image')));
$('restart-button').addEventListener('click',()=>openDialog('restart-dialog'));
function reset(){session=createSession();editing=false;currentArtifact='boxes';document.querySelectorAll('dialog[open]').forEach(d=>d.close());['printable-record','matrix-body','mobile-matrix','metrics','result-observation'].forEach(id=>$(id).replaceChildren());history.replaceState(null,'','#offer');renderScene(0,true);announce('All decisions and private notes have been cleared.');return {choice:null,answered:0};}
$('confirm-restart').addEventListener('click',reset);
// WebMCP actions use the same validation and UI handlers. Notes are never exposed by state tools.
function registerTools(){if(!document.modelContext?.registerTool)return;const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{/* Optional browser capability. */}};const empty=input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');};const base={annotations:{readOnlyHint:false,untrustedContentHint:false}};
register({...base,name:'inspect_artifact',title:'Inspect an artifact',description:'Open an original fictional artifact photograph. No data is submitted.',inputSchema:{type:'object',properties:{artifact:{type:'string',enum:ARTIFACTS.map(a=>a.id)}},required:['artifact'],additionalProperties:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='artifact'))throw new Error('Expected an artifact');const result=selectArtifact(input.artifact);openDialog('artifact-dialog');return result;}});
register({...base,name:'select_exhibit_choice',title:'Choose a response',description:'Choose a response for the currently displayed fictional situation. Kept in page memory only.',inputSchema:{type:'object',properties:{choice:{type:'string',enum:CHOICES.map(c=>c.id)}},required:['choice'],additionalProperties:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='choice'))throw new Error('Expected a choice');if(!$('results').hidden)throw new Error('Open a situation to revise it first');return choose(input.choice);}});
register({...base,name:'reset_exhibit_choice',title:'Clear the exhibit',description:'Clear all decisions and private notes and return to the original offer.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute(input){empty(input);return reset();}});
register({...base,name:'navigate_exhibit_scene',title:'Open a situation',description:'Open a reached situation or the completed decision matrix. Unanswered situations cannot be skipped.',inputSchema:{type:'object',properties:{scene:{type:'string',enum:[...SCENES.map(s=>s.id),'record']}},required:['scene'],additionalProperties:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='scene')||![...SCENES.map(s=>s.id),'record'].includes(input.scene))throw new Error('Invalid scene');editing=calculateMetrics(session).complete&&input.scene!=='record';history.pushState(null,'',`#${input.scene}`);route();return {scene:$('results').hidden?SCENES[currentScene].id:'record'};}});
register({...base,name:'read_exhibit_state',title:'Read the exhibit state',description:'Read the selected artifact, displayed situation, decisions and calculated counts. Does not expose private notes.',annotations:{readOnlyHint:true,untrustedContentHint:false},inputSchema:{type:'object',properties:{},additionalProperties:false},execute(input){empty(input);return {artifact:currentArtifact,scene:$('results').hidden?SCENES[currentScene].id:'record',choice:session.answers[SCENES[currentScene].id],answers:{...session.answers},metrics:calculateMetrics(session)};}});}
window.addEventListener('pageshow',event=>{if(event.persisted)reset();});
route(false);selectArtifact('boxes');registerTools();
